      "dependencies",
      "optionalDependencies",
      "peerDependencies",
      "devDependencies",
      "overrides",
      "resolutions",
    ])
      delete data[field];
    return JSON.stringify(data);
  };
  assert.equal(
    strip(after),
    strip(before),
    "Maintenance cannot change scripts, versions, exports, or other non-dependency fields",
  );
}

